K, W, C = 'Knowledge', 'Wisdom', 'Command'
S, R = 'stated', 'reflection'
def ins(t, b, text): return {'type': t, 'basis': b, 'text': text}
def keeps(t): return {'dir': 'keeps', 'text': t}
def loses(t): return {'dir': 'loses', 'text': t}
def between(t): return {'dir': 'between', 'text': t}
AGREE = between("Hebrew, Greek, Latin and King James agree in substance; only the rendering of the divine name and small turns of phrase differ.")
CALF = [loses("Hebrew 'bull' is lost."), keeps("Greek 'calf'."), between("The Latin has 'calf'; the King James 'bullock'.")]
TENT = [loses("Hebrew 'Tent of Meeting' is lost."), keeps("Greek 'Tent of Testimony'."), between("The Latin has 'tabernacle of the testimony'; the King James 'tabernacle of the congregation'.")]
GOAT = [keeps("Greek 'male young goat from the goats' for the Hebrew's 'goat'."), between("The Latin and King James have 'goat' or 'kid of the goats'.")]
AZ = [loses("Hebrew 'Azazel' is lost as a name."), keeps("Greek 'the one sent away' (apopompaios), read through the dismissal rite; the source leaves the Hebrew referent and the Greek nuance unsettled."), between("The Latin has 'the emissary goat' (caper emissarius); the King James 'scapegoat'.")]
PROP = between("The Latin renders atonement as the priest's prayer; the Greek as propitiation for persons and expiation for the sanctuary's objects.")

def v(received, explain, shared, k, w, lost, entries=None, cmd=None):
    inst = [ins(K, S, k)]
    if cmd: inst.append(ins(C, S, cmd))
    inst.append(ins(W, R, w))
    return {'received': received, 'explain': explain, 'shared': shared, 'instructions': inst, 'entries': entries if entries is not None else ['high-priest'], 'lost': lost}

